import{_ as e,C as n,c as i,o as t,j as r,G as l,b as a,a0 as s,a as o,w as u,a1 as h}from"./chunks/framework.DKRgXLPU.js";const g=JSON.parse('{"title":"Trainingslager: Wochenendleitfaden","description":"","frontmatter":{},"headers":[],"relativePath":"de/training-camp.md","filePath":"de/training-camp.md"}');const d=e({name:"de/training-camp.md"},[["render",function(e,g,d,p,c,m){const f=n("AdBanner"),b=n("Mermaid"),k=n("AdInArticle");return t(),i("div",null,[g[2]||(g[2]=r("h1",{id:"trainingslager-wochenendleitfaden",tabindex:"-1"},[o("Trainingslager: Wochenendleitfaden "),r("a",{class:"header-anchor",href:"#trainingslager-wochenendleitfaden","aria-label":'Permalink to "Trainingslager: Wochenendleitfaden"'},"​")],-1)),l(f),g[3]||(g[3]=r("h2",{id:"wie-man-ein-wochenend-trainingslager-fur-10-20-spieler-durchfuhrt",tabindex:"-1"},[o("Wie man ein Wochenend-Trainingslager für 10-20 Spieler durchführt "),r("a",{class:"header-anchor",href:"#wie-man-ein-wochenend-trainingslager-fur-10-20-spieler-durchfuhrt","aria-label":'Permalink to "Wie man ein Wochenend-Trainingslager für 10-20 Spieler durchführt"'},"​")],-1)),g[4]||(g[4]=r("p",null,"Dieser umfassende Leitfaden hilft Ihnen bei der Organisation und Durchführung eines Wochenend-Trainingscamps, das Theorie, Praxis und Wettkampf vereint. Kombinieren Sie die mentalen Trainingsinhalte dieser Website mit praktischen Übungen auf der Piste, um maximale Wirkung zu erzielen.",-1)),g[5]||(g[5]=r("p",null,"::: Tipp: Die Philosophie des Trainingslagers Theorie ohne Praxis ist bloß Information. Praxis ohne Theorie ist bloß Wiederholung. Wettbewerb ohne Reflexion ist bloßes Spielen. Dieses Wochenende vereint alle drei Aspekte für ein transformatives Lernerlebnis. :::",-1)),(t(),a(h,null,{default:u(()=>[l(b,{id:"mermaid-14",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BWeekend%20Camp%5D%20--%3E%20B%5BFriday%3A%20Theory%5D%0A%20%20%20%20B%20--%3E%20C%5BSaturday%3A%20Practice%5D%0A%20%20%20%20C%20--%3E%20D%5BSunday%3A%20Competition%5D%0A%20%20%20%20D%20--%3E%20E%5BIntegration%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23f3e5f5%0A"})]),fallback:u(()=>[...g[0]||(g[0]=[o(" Loading... ",-1)])]),_:1})),g[6]||(g[6]=s('<h2 id="vorbereitung-des-camps" tabindex="-1">Vorbereitung des Camps <a class="header-anchor" href="#vorbereitung-des-camps" aria-label="Permalink to &quot;Vorbereitung des Camps&quot;">​</a></h2><h3 id="gruppengroße-und-struktur" tabindex="-1">Gruppengröße und -struktur <a class="header-anchor" href="#gruppengroße-und-struktur" aria-label="Permalink to &quot;Gruppengröße und -struktur&quot;">​</a></h3><p><strong>Optimal:</strong> 10-20 Spieler</p><ul><li><strong>Kleines Camp (10-12):</strong> Intimerer, intensiverer Austausch</li><li><strong>Großes Camp (16-20):</strong> Vielfältigere Perspektiven, erfordert Untergruppen</li></ul><p><strong>Teamstruktur:</strong></p><ul><li>Für Training und Wettkampf in Teams von 3-4 Personen aufteilen.</li><li>Verschiedene Fähigkeitsstufen und Spielstile mischen</li><li>Die Teams sollten im Laufe des Wochenendes rotieren.</li></ul><h3 id="personalbedarf" tabindex="-1">Personalbedarf <a class="header-anchor" href="#personalbedarf" aria-label="Permalink to &quot;Personalbedarf&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rolle</th><th>Verantwortlichkeiten</th><th>Menge</th></tr></thead><tbody><tr><td><strong>Koordinator/in für mentale Leistungsfähigkeit</strong></td><td>Theorieeinheiten und Gruppendynamik leiten</td><td>1</td></tr><tr><td><strong>Technischer Coach</strong></td><td>Training beaufsichtigen, Feedback geben</td><td>1-2</td></tr><tr><td><strong>Wettkampfleitung</strong></td><td>Turnierorganisation, Logistikmanagement</td><td>1</td></tr><tr><td><strong>Hilfspersonal</strong></td><td>Mahlzeiten, Aufbau, Verwaltung</td><td>1-2</td></tr></tbody></table><h3 id="standortanforderungen" tabindex="-1">Standortanforderungen <a class="header-anchor" href="#standortanforderungen" aria-label="Permalink to &quot;Standortanforderungen&quot;">​</a></h3><p>::: Informationen zum Anlagenbedarf <strong>Piste:</strong></p><ul><li>Mehrere Gelände (mindestens 3-4 Pisten)</li><li>Wenn möglich, unterschiedliche Oberflächen (Kies, Sand, hart)</li><li>Beleuchtung für das Abendspiel</li></ul><p><strong>Innenraum:</strong></p><ul><li>Platz für 20 Personen im Kreis (Theoriesitzungen)</li><li>Von der Piste getrennt</li><li>Whiteboard/Projektor</li><li>Bequeme Sitzgelegenheiten</li></ul><p><strong>Unterkunft:</strong></p><ul><li>Vor Ort oder in unmittelbarer Nähe (fußläufig erreichbar)</li><li>Mehrbettzimmer fördern die Bindung zwischen den Partnern.</li><li>Ein ruhiger Ort zum Nachdenken</li></ul><p><strong>Gastronomie:</strong></p><ul><li>Ernährungsorientierte Mahlzeiten (siehe <a href="./food">Lebensmittelpyramide</a>)</li><li>Vermeiden Sie Zuckerschocks</li><li>Trinkstationen :::</li></ul><h3 id="materialliste" tabindex="-1">Materialliste <a class="header-anchor" href="#materialliste" aria-label="Permalink to &quot;Materialliste&quot;">​</a></h3><p>::: Details Vollständige Materialliste <strong>Theoriesitzungen:</strong></p><ul><li>[ ] Stühle für einen Kreis (keine Tische)</li><li>[ ] Boule und Cochonnet für die Mitte</li><li>[ ] Flipcharts und Marker</li><li>[ ] Haftnotizen</li><li>[ ] Arbeitsblätter (Benutzerhandbuch, Innerer Kritiker usw.)</li><li>[ ] Papier und Stifte</li><li>[ ] Projektor (für Website-Inhalte)</li></ul><p><strong>Übungseinheiten:</strong></p><ul><li>[ ] Maßband</li><li>[ ] Kegel/Markierungen für Bohrer</li><li>[ ] Videokamera/Stativ</li><li>[ ] Klemmbrett und Papier (Tracking)</li><li>[ ] Pfeife</li></ul><p><strong>Wettbewerb:</strong></p><ul><li>[ ] Punktetabellen</li><li>[ ] Turnierbaum</li><li>[ ] Preise/Anerkennung</li><li>[ ] Erste-Hilfe-Set</li></ul><p><strong>Logistik:</strong></p><ul><li>[ ] Namensschilder</li><li>[ ] Teilnehmerliste mit Kontaktdaten</li><li>[ ] Notfallkontaktinformationen</li><li>[ ] Wasserflaschen</li><li>[ ] Sonnenschutzmittel</li><li>[ ] Taschentücher (für emotionale Arbeit!) :::</li></ul><h2 id="wochenendprogramm" tabindex="-1">Wochenendprogramm <a class="header-anchor" href="#wochenendprogramm" aria-label="Permalink to &quot;Wochenendprogramm&quot;">​</a></h2><h3 id="freitagabend-3-stunden" tabindex="-1">Freitagabend (3 Stunden) <a class="header-anchor" href="#freitagabend-3-stunden" aria-label="Permalink to &quot;Freitagabend (3 Stunden)&quot;">​</a></h3><p><strong>18:00-18:30 - Ankunft &amp; Begrüßung</strong></p><ul><li>Einchecken</li><li>Zimmerzuteilung</li><li>Wochenendübersicht</li></ul><p><strong>18:30-19:30 - Abendessen</strong></p><ul><li>Ernährungsorientierte Mahlzeit</li><li>Informelle Vorstellungen</li></ul><p><strong>19:30-22:30 - Theorieeinheit: Grundlagen</strong></p><p>Nutzen Sie den <a href="./workshop">Workshop-Leitfaden</a> für eine detaillierte Anleitung:</p><ol><li><strong>Grundregeln (15 Min.)</strong> – Psychologische Sicherheit schaffen</li><li><strong>Check-in-Matrix (20 Min.)</strong> – Gruppenenergie einschätzen.</li><li><strong>Der Eisberg (30 Min.)</strong> – Innere Gedanken erforschen</li><li><strong>Benutzerhandbuch (45 Min.)</strong> – Teamverständnis aufbauen</li><li><strong>Angst mit Hut (45 Min.)</strong> – Isolation durchbrechen</li><li><strong>Auschecken (15 Min.)</strong> – Den Kreislauf schließen.</li></ol><p><strong>22:30 - Freizeit</strong></p><ul><li>Informelles geselliges Beisammensein</li><li>Ruhe und Besinnung</li></ul>',37)),(t(),a(h,null,{default:u(()=>[l(b,{id:"mermaid-435",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFriday%20Theory%5D%20--%3E%20B%5BPsychological%20Safety%5D%0A%20%20%20%20B%20--%3E%20C%5BSelf-Awareness%5D%0A%20%20%20%20C%20--%3E%20D%5BTeam%20Understanding%5D%0A%20%20%20%20D%20--%3E%20E%5BReady%20for%20Practice%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A"})]),fallback:u(()=>[...g[1]||(g[1]=[o(" Loading... ",-1)])]),_:1})),l(k),g[7]||(g[7]=s('<h3 id="samstag-ganztagig-theorie-praxis" tabindex="-1">Samstag (Ganztägig - Theorie + Praxis) <a class="header-anchor" href="#samstag-ganztagig-theorie-praxis" aria-label="Permalink to &quot;Samstag (Ganztägig - Theorie + Praxis)&quot;">​</a></h3><p><strong>08:00-09:00 - Frühstück &amp; Achtsamkeit</strong></p><ul><li>Ruhiges Frühstück</li><li>Optionale 15-minütige geführte Meditation</li><li>Ziele für den Tag setzen</li></ul><p><strong>09:00-10:30 Uhr – Theorieeinheit: Inhalte und Erfahrungen verknüpfen</strong></p><p>Wählen Sie 3-4 Themen von der Website der Akademie und erkunden Sie das innere Spiel:</p><p><strong>Beispielthemen:</strong></p><ol><li><p><strong><a href="./education/nutrition/">Ernährung</a></strong> (20 Min.)</p><ul><li>„Wie verändert sich Ihre Essenswahl unter Druck?“</li><li>&quot;Esst ihr, was euer Körper braucht oder was eure Angst verlangt?&quot;</li><li>Übung: Ernährungsplan für den Wettkampftag</li></ul></li><li><p><strong><a href="./education/mental-strength/">Mentale Stärke</a></strong> (25 Min.)</p><ul><li>&quot;Wie stehst du zum Scheitern?&quot;</li><li>„Wie redet man mit sich selbst, nachdem man einen Fehlschuss kassiert hat?“</li><li>Aktivität: Den inneren Kritiker in einen inneren Coach umwandeln</li></ul></li><li><p><strong><a href="./education/mindfulness/">Achtsamkeit</a></strong> (25 Min.)</p><ul><li>&quot;Wohin gehen Ihre Gedanken während der Pause vor dem Wurf?&quot;</li><li>&quot;Was reißt dich aus dem gegenwärtigen Moment heraus?&quot;</li><li>Übung: 5-minütiger Körperscan</li></ul></li><li><p><strong><a href="./education/tactics/">Taktiken</a></strong> (20 Min.)</p><ul><li>&quot;Basiert Ihre Schusswahl auf Strategie oder Angst?&quot;</li><li>&quot;Wann sollte man auf Nummer sicher gehen und wann Risiken eingehen?&quot;</li><li>Diskussion: Risikoprofile in der Gruppe</li></ul></li></ol><p><strong>10:30-10:45 - Pause</strong></p><p><strong>10:45-12:30 - Integration auf der Piste: Übungen mit mentaler Konzentration</strong></p><p><strong>Übung 1: Den Schuss ansagen (30 Min.)</strong></p><p>Aus dem <a href="./workshop">Workshop-Leitfaden</a> – Üben Sie, Ihre Absicht und Ihren Zweifel zu übernehmen:</p><ol><li>Das Ziel ankündigen: „Ich schieße auf das Eisen“</li><li>Geben Sie Ihr Selbstvertrauen an: „Ich würde sagen, ich bin eine 7 von 10.“</li><li>Benennen Sie den inneren Gedanken: „Meine innere Stimme macht sich Sorgen wegen des Rückwärtsdralls.“</li><li>Führe den Schuss aus.</li><li>Reflektiere: „Was ist passiert? Was hast du daraus gelernt?“</li></ol><p><strong>Übung 2: Kognitive Interferenz (30 Min.)</strong></p><p>Testen Sie, ob die Technik automatisiert ist:</p><ul><li>Der Koordinator stellt komplexe Fragen, während der Spieler schießt.</li><li>&quot;Nenne 5 Hauptstädte&quot; oder &quot;Zähle von 100 in 7er-Schritten rückwärts&quot;</li><li>Erfolg = Die Technik ist implizit, sie wird nicht bewusst verarbeitet</li></ul><p><strong>Übung 3: Praxis mit der Bedienungsanleitung (30 Min.)</strong></p><p>Die Benutzerhandbücher ab Freitag anwenden:</p><ul><li>Spielt in Dreierteams Nach jedem Schuss reagieren die Teammitglieder gemäß der Bedienungsanleitung.</li><li>„Marc braucht nach einem Fehlwurf Ruhe“ – das Team respektiert das.</li><li>Nachbesprechung: „Wie hat es sich angefühlt, verstanden zu werden?“</li></ul><p><strong>12:30-14:00 Uhr - Mittagessen &amp; Pause</strong></p><ul><li>Ernährungsorientierte Mahlzeit</li><li>Zeit der Stille zur Besinnung</li><li>Optional: Individuelle Check-ins mit dem Koordinator</li></ul><p><strong>14:00-17:00 Uhr - Übungseinheit: Geländeanpassung</strong></p><p><strong>Ziel:</strong> Anpassungsfähigkeit und mentale Flexibilität aufbauen</p><p><strong>Aufstellen:</strong></p><ul><li>Rotieren Sie durch 3-4 verschiedene Gelände/Pisten</li><li>45 Minuten pro Geländeabschnitt</li><li>Fokus auf mentale Anpassung, nicht nur auf technische Anpassung</li></ul><p><strong>Rotationsstruktur:</strong></p><table tabindex="0"><thead><tr><th>Gelände</th><th>Mentale Konzentration</th><th>Übung</th></tr></thead><tbody><tr><td><strong>Gelände 1: Weich/Sand</strong></td><td>Akzeptanz der Ungewissheit</td><td>„Die Donnée – akzeptiere, was ist“</td></tr><tr><td><strong>Gelände 2: Hart/Schotter</strong></td><td>Präzision unter Druck</td><td>&quot;Vertraue deiner Technik&quot;</td></tr><tr><td><strong>Gelände 3: Uneben</strong></td><td>Emotionsregulation</td><td>&quot;Bleib ruhig, wenn es unfair ist&quot;</td></tr><tr><td><strong>Gelände 4: Wettbewerb</strong></td><td>Zugriff auf den Flow-Zustand</td><td>&quot;Finde die Zone&quot;</td></tr></tbody></table><p><strong>Moderation:</strong> Der technische Trainer gibt Feedback zur Technik.</p><ul><li>MPC fragt: &quot;Was geht Ihnen gerade durch den Kopf?&quot;</li><li>Spielertagebuch zwischen den Rotationen</li></ul><p><strong>17:00-18:00 Uhr - Pause &amp; Reflexion</strong></p><ul><li>Individuelles Tagebuch</li><li>&quot;Was hast du heute über dich selbst gelernt?&quot;</li><li>&quot;Was ist eine Sache, die du morgen anders machen wirst?&quot;</li></ul><p><strong>18:00-19:00 Uhr - Abendessen</strong></p><p><strong>19:00-21:00 Uhr - Abendtheorie: Tiefe Verletzlichkeit</strong></p><p><strong>Aktivität 1: Den inneren Kritiker neu definieren (45 Min.)</strong></p><p>Das vollständige Protokoll finden Sie im <a href="./workshop">Workshop-Leitfaden</a>:</p><ol><li>Identifizieren Sie die genaue Formulierung des Kritikers.</li><li>Sich als innerer Coach neu interpretieren</li><li>Partnerpraxis</li></ol><p><strong>Aktivität 2: Wettkampfvorbereitung (45 Min.)</strong></p><p>Morgen ist Wettkampftag. Bereite dich mental vor:</p><ol><li><p><strong>Visualisierung (15 Min.)</strong></p><ul><li>Augen schließen</li><li>Stell dir die perfekte Aufnahme vor Spüre das Selbstvertrauen</li><li>Beachten Sie die Ruhe</li></ul></li><li><p><strong>Teamprotokolle (20 Min.)</strong></p><ul><li>Signale zur Unterstützung erzeugen</li><li>&quot;Ich brauche einen Reset&quot; = Berührungskugeln</li><li>&quot;Ich brauche Ermutigung&quot; = Faustgruß</li><li>„Ich brauche Abstand“ = Schritt zurücktreten</li></ul></li><li><p><strong>Ziele setzen (10 Min.)</strong></p><ul><li>„Morgen werde ich mich auf … konzentrieren.“</li><li>„Mein Ziel ist nicht zu gewinnen, sondern...“</li><li>&quot;Ich werde üben...&quot;</li></ul></li></ol><p><strong>Auschecken (30 Min.)</strong> Teile eine deiner Ängste bezüglich morgen.</p><ul><li>Eine gemeinsame Absicht teilen</li><li>Gruppenunterstützung</li></ul><p><strong>21:00 Uhr - Freizeit</strong></p><ul><li>Früh ins Bett (morgen Wettkampf!)</li><li>Stille Betrachtung</li></ul><h3 id="sonntag-wettkampftag" tabindex="-1">Sonntag (Wettkampftag) <a class="header-anchor" href="#sonntag-wettkampftag" aria-label="Permalink to &quot;Sonntag (Wettkampftag)&quot;">​</a></h3><p><strong>08:00-09:00 - Frühstück &amp; Mentale Vorbereitung</strong></p><ul><li>Leichtes Frühstück (siehe <a href="./education/nutrition/">Ernährungsleitfaden</a>)</li><li>15-minütige Achtsamkeitsübung</li><li>Teambesprechungen</li></ul><p><strong>09:00-09:30 - Wettbewerbsbesprechung</strong></p><p><strong>Format:</strong> Rundenturnier</p><ul><li>Teams von 3</li><li>Spielen Sie bis 13 Punkte</li><li>Jeder spielt jeden</li><li>Fokus auf den PROZESS, nicht auf das Ergebnis</li></ul><p><strong>Die Besonderheit: Bewertung der mentalen Leistungsfähigkeit</strong></p><p>::: Tipp: Doppeltes Punktesystem <strong>Traditionell:</strong> Gewonnene Punkte <strong>Mentale Leistungsfähigkeit:</strong> Bewertet mit dem MPC</p><p>Punkte für mentale Leistungsfähigkeit (0-5 pro Spiel):</p><ul><li>Verwendete Werkzeuge aus dem Benutzerhandbuch</li><li>Unterstützte Teammitglieder effektiv</li><li>Den inneren Kritiker im Griff behalten</li><li>Im Hier und Jetzt geblieben (nicht in der Vergangenheit verweilt)</li><li>Nachgewiesene psychologische Sicherheit</li></ul><p><strong>Sieger:</strong> Beste Gesamtpunktzahl (traditionell + mental) :::</p><p><strong>09:30-13:00 Uhr - Vormittagswettbewerb</strong></p><ul><li>Rundenspiele</li><li>MPC beobachtet und bewertet Der technische Trainer gibt zwischen den Spielen kurzes Feedback.</li><li>Trink- und Snackpausen</li></ul><p><strong>13:00-14:00 Uhr - Mittagessen</strong></p><ul><li>Ernährungsorientiert</li><li>Informelle Reflexion</li><li>Ausruhen</li></ul><p><strong>14:00-17:00 Uhr - Nachmittagswettbewerb</strong></p><ul><li>Fortsetzung des Rundlaufs</li><li>Halbfinale und Finale</li><li>Zunehmender Druck</li><li>Die Erkenntnisse des Morgens anwenden</li></ul><p><strong>17:00-17:30 - Preisverleihung &amp; Ehrungen</strong></p><p><strong>Kategorien:</strong></p><ul><li>Traditioneller Gewinner</li><li>Gewinner der mentalen Leistungsfähigkeit</li><li>Größte Verbesserung</li><li>Bester Teamkollege</li><li>Tapferkeitsauszeichnung (für besonders schutzbedürftige Personen)</li></ul><p><strong>17:30-19:00 - Abschließende Reflexionsrunde</strong></p><p><strong>Entscheidend:</strong> Hier wird das Gelernte gefestigt.</p><p><strong>Struktur:</strong></p><p><strong>1. Individuelle Reflexion (15 Min.)</strong> Ins Tagebuch schreiben:</p><ul><li>Was hast du dieses Wochenende über dich selbst gelernt?</li><li>Was hat Sie überrascht? Was werden Sie anders machen?</li><li>Was nimmst du mit nach Hause?</li></ul><p><strong>2. Austausch in Kleingruppen (30 Min.)</strong> Gruppen von 4-5 Personen:</p><ul><li>Wichtige Erkenntnisse teilen Was hat am meisten Anklang gefunden? Was war am schwierigsten?</li><li>Was war am wertvollsten?</li></ul><p><strong>3. Vollständige Gruppenintegration (30 Minuten)</strong> Kreis bilden:</p><ul><li>Jeder teilt EINE zentrale Erkenntnis mit.</li><li>MPC validiert und verbindet Themes</li><li>Diskutieren Sie: „Wie werden Sie dies anwenden?“</li></ul><p><strong>4. Verpflichtungen (15 Min.)</strong> Jede Person gibt eine Verpflichtung ab.</p><ul><li>&quot;Bei meinem nächsten Wettkampf werde ich...&quot;</li><li>Gruppenzeugen und Unterstützer</li></ul><p><strong>5. Abschluss (15 Min.)</strong></p><ul><li>Vielen Dank an die Teilnehmer für ihren Mut</li><li>Auf die Vertraulichkeit hinweisen</li><li>Kontakte austauschen</li><li>Nachbereitung planen (optionale Online-Sitzung)</li></ul><p><strong>19:00 Uhr - Abendessen &amp; Abreise</strong></p>',76)),l(k),g[8]||(g[8]=s('<h2 id="moderationstipps" tabindex="-1">Moderationstipps <a class="header-anchor" href="#moderationstipps" aria-label="Permalink to &quot;Moderationstipps&quot;">​</a></h2><h3 id="balancetheorie-und-praxis" tabindex="-1">Balancetheorie und -praxis <a class="header-anchor" href="#balancetheorie-und-praxis" aria-label="Permalink to &quot;Balancetheorie und -praxis&quot;">​</a></h3><p>::: Warnung: Überlaste die Theorie nicht! <strong>Der Fehler:</strong> Zu viel Gerede, zu wenig Taten</p><p><strong>Die Bilanz:</strong></p><ul><li>Theorie schafft Bewusstsein Übung macht den Meister</li><li>Integration von Wettbewerbstests</li><li>Reflexion festigt das Lernen</li></ul><p><strong>Faustregel:</strong> 30 % Theorie, 40 % Praxis, 20 % Wettbewerb, 10 % Reflexion :::</p><h3 id="management-der-gruppendynamik" tabindex="-1">Management der Gruppendynamik <a class="header-anchor" href="#management-der-gruppendynamik" aria-label="Permalink to &quot;Management der Gruppendynamik&quot;">​</a></h3><p><strong>Der wettbewerbsfähige Alpha:</strong></p><ul><li>Will um jeden Preis gewinnen</li><li>Widersteht Anfälligkeit</li><li><strong>Strategie:</strong> Wettbewerbsorientierung in die Bewertung der mentalen Leistungsfähigkeit kanalisieren</li></ul><p><strong>Der stille Beobachter:</strong></p><ul><li>Nimmt alles in sich auf, teilt aber nichts.</li><li><strong>Strategie:</strong> Niedrigriskante Einstiegsmöglichkeiten schaffen, Beobachtung als Teilnahme anerkennen</li></ul><p><strong>Der Skeptiker:</strong></p><ul><li>&quot;Dieses ganze Gefühlszeug funktioniert nicht.&quot;</li><li><strong>Strategie:</strong> Verbales Aikido – Ausrichten und Pivotieren (siehe <a href="./workshop">Workshop-Leitfaden</a>)</li></ul><p><strong>Der/Die Überteiler/in:</strong></p><ul><li>Beherrscht die Diskussion</li><li><strong>Strategie:</strong> „Vielen Dank, hören wir uns nun die Meinungen anderer an.“</li></ul><h3 id="umgang-mit-emotionalen-momenten" tabindex="-1">Umgang mit emotionalen Momenten <a class="header-anchor" href="#umgang-mit-emotionalen-momenten" aria-label="Permalink to &quot;Umgang mit emotionalen Momenten&quot;">​</a></h3><p><strong>Jemand weint während Fear in a Hat:</strong></p><ul><li>✅ Normalisieren: „Tränen sind ein Zeichen von Mut, nicht von Schwäche“</li><li>✅ Bieten Sie Taschentücher an, aber hetzen Sie nicht.</li><li>✅ Fragen Sie: &quot;Was brauchen Sie jetzt?&quot;</li><li>❌ Nicht: „Es ist okay, weine nicht“</li></ul><p><strong>Konflikt zwischen Spielern:</strong></p><ul><li>✅ Pause und Ansprache</li><li>✅ &quot;Was passiert gerade?&quot;</li><li>✅ Als Lernmoment nutzen</li><li>❌ Nicht: Ignorieren oder verharmlosen</li></ul><p><strong>Jemand schaltet ab:</strong></p><ul><li>✅ Privat während der Pause einchecken</li><li>✅ „Mir ist aufgefallen, dass du still geworden bist. Was ist los?“</li><li>✅ Bieten Sie Optionen an: auf andere Weise teilnehmen, eine Pause einlegen</li><li>❌ Nicht tun: Öffentlich anprangern</li></ul><h2 id="nachbereitung-des-camps" tabindex="-1">Nachbereitung des Camps <a class="header-anchor" href="#nachbereitung-des-camps" aria-label="Permalink to &quot;Nachbereitung des Camps&quot;">​</a></h2><h3 id="sofort-24-48-stunden" tabindex="-1">Sofort (24-48 Stunden) <a class="header-anchor" href="#sofort-24-48-stunden" aria-label="Permalink to &quot;Sofort (24-48 Stunden)&quot;">​</a></h3><p><strong>An alle Teilnehmer senden:</strong></p><ul><li>Dankesnachricht</li><li>Zusammenfassung der wichtigsten Erkenntnisse</li><li>Fotos vom Wochenende</li><li>Kontaktliste (mit Genehmigung)</li><li>Link zu Ressourcen auf der Website</li></ul><p><strong>Individuelle Check-ins:</strong></p><ul><li>Schreibe jedem, der viel geteilt hat</li><li>&quot;Wie fühlst du dich mit Blick aufs Wochenende?&quot;</li><li>Beheben Sie alle verbleibenden Sicherheitslücken</li></ul><h3 id="kurzfristig-2-wochen" tabindex="-1">Kurzfristig (2 Wochen) <a class="header-anchor" href="#kurzfristig-2-wochen" aria-label="Permalink to &quot;Kurzfristig (2 Wochen)&quot;">​</a></h3><p><strong>Optionale Online-Sitzung (60-90 Min.):</strong></p><ul><li>Wie haben Sie die gewonnenen Erkenntnisse angewendet?</li><li>Was funktioniert? Was ist schwierig?</li><li>Unterstützung und Problemlösung durch Gleichaltrige</li><li>Verpflichtungen bekräftigen</li></ul><h3 id="langfristig-1-3-monate" tabindex="-1">Langfristig (1-3 Monate) <a class="header-anchor" href="#langfristig-1-3-monate" aria-label="Permalink to &quot;Langfristig (1-3 Monate)&quot;">​</a></h3><p><strong>Umfrageteilnehmer:</strong></p><ul><li>Was ist in eurem Spiel anders? Welche Werkzeuge verwenden Sie noch? Was würde das nächste Camp verbessern? Würden Sie es weiterempfehlen?</li></ul><p><strong>Auswirkungen auf die Strecke:</strong></p><ul><li>Wettbewerbsergebnisse</li><li>Selbstberichtetes Selbstvertrauen</li><li>Teamdynamik</li><li>Fortgesetztes Engagement</li></ul><h2 id="anpassung-an-unterschiedliche-gruppengroßen" tabindex="-1">Anpassung an unterschiedliche Gruppengrößen <a class="header-anchor" href="#anpassung-an-unterschiedliche-gruppengroßen" aria-label="Permalink to &quot;Anpassung an unterschiedliche Gruppengrößen&quot;">​</a></h2><h3 id="kleines-camp-10-12-spieler" tabindex="-1">Kleines Camp (10-12 Spieler) <a class="header-anchor" href="#kleines-camp-10-12-spieler" aria-label="Permalink to &quot;Kleines Camp (10-12 Spieler)&quot;">​</a></h3><p><strong>Vorteile:</strong></p><ul><li>Vertiefter Austausch</li><li>Mehr individuelle Betreuung</li><li>Stärkere Bindungen</li></ul><p><strong>Anpassungen:</strong></p><ul><li>Eine einzige Gruppe für die gesamte Theorie</li><li>Mehr Zeit pro Person für Aktivitäten</li><li>Intimes Wettbewerbsformat</li></ul><h3 id="großes-camp-16-20-spieler" tabindex="-1">Großes Camp (16-20 Spieler) <a class="header-anchor" href="#großes-camp-16-20-spieler" aria-label="Permalink to &quot;Großes Camp (16-20 Spieler)&quot;">​</a></h3><p><strong>Vorteile:</strong></p><ul><li>Unterschiedliche Perspektiven</li><li>Mehr Wettbewerbsvielfalt</li><li>Skaleneffekte</li></ul><p><strong>Anpassungen:</strong></p><ul><li>Aufteilung in 2 Gruppen für einige Theorieeinheiten</li><li>2 MPC/Moderatoren werden benötigt</li><li>Größerer Turnierbaum</li><li>Strukturiertere Rotationen</li></ul><h2 id="budgetuberlegungen" tabindex="-1">Budgetüberlegungen <a class="header-anchor" href="#budgetuberlegungen" aria-label="Permalink to &quot;Budgetüberlegungen&quot;">​</a></h2><h3 id="einnahmen" tabindex="-1">Einnahmen <a class="header-anchor" href="#einnahmen" aria-label="Permalink to &quot;Einnahmen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Artikel</th><th>Preis pro Person</th><th>20 Personen</th><th>10 Personen</th></tr></thead><tbody><tr><td><strong>Anmeldung</strong></td><td>150–250 €</td><td>3.000–5.000 €</td><td>1.500–2.500 €</td></tr></tbody></table><h3 id="ausgaben" tabindex="-1">Ausgaben <a class="header-anchor" href="#ausgaben" aria-label="Permalink to &quot;Ausgaben&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kategorie</th><th>Kosten</th><th>Anmerkungen</th></tr></thead><tbody><tr><td><strong>Objektmiete</strong></td><td>500–1.000 €</td><td>Wochenendpreis</td></tr><tr><td><strong>Unterkunft</strong></td><td>40-60 €/Person/Nacht</td><td>Mehrbettzimmer</td></tr><tr><td><strong>Mahlzeiten</strong></td><td>30-40 €/Person/Tag</td><td>6 Mahlzeiten</td></tr><tr><td><strong>Mitarbeiter</strong></td><td>500-1.000 €</td><td>MPC + Trainer</td></tr><tr><td><strong>Materialien</strong></td><td>100-200 €</td><td>Arbeitsblätter, Zubehör</td></tr><tr><td><strong>Preise</strong></td><td>100–200 €</td><td>Anerkennungsartikel</td></tr></tbody></table><p><strong>Gesamtpreis pro Person:</strong> 120-180 € <strong>Marge:</strong> 30-70 €/Person (oder Kostendeckung für Gemeinschaftsprojekte)</p><h2 id="erfolgskennzahlen" tabindex="-1">Erfolgskennzahlen <a class="header-anchor" href="#erfolgskennzahlen" aria-label="Permalink to &quot;Erfolgskennzahlen&quot;">​</a></h2><h3 id="sofortindikatoren" tabindex="-1">Sofortindikatoren <a class="header-anchor" href="#sofortindikatoren" aria-label="Permalink to &quot;Sofortindikatoren&quot;">​</a></h3><ul><li>[ ] Psychologische Sicherheitsbewertung (1-10, Durchschnitt &gt;7)</li><li>[ ] Beteiligungsrate (&gt;80 % aktives Teilen)</li><li>[ ] Abschlussquote (&gt;90 % bleiben das gesamte Wochenende)</li><li>[ ] Zufriedenheitswert (1-10 Durchschnitt &gt;8)</li></ul><h3 id="langfristige-indikatoren" tabindex="-1">Langfristige Indikatoren <a class="header-anchor" href="#langfristige-indikatoren" aria-label="Permalink to &quot;Langfristige Indikatoren&quot;">​</a></h3><ul><li>[ ] Verhaltensänderung (Einsatz von Instrumenten im Wettbewerb)</li><li>[ ] Leistungsverbesserung (Selbstauskunft)</li><li>[ ] Gemeinschaftsbildung (in Kontakt bleiben)</li><li>[ ] Weiterempfehlungen (Empfehlungen an andere)</li></ul><h2 id="haufige-fehler-die-sie-vermeiden-sollten" tabindex="-1">Häufige Fehler, die Sie vermeiden sollten <a class="header-anchor" href="#haufige-fehler-die-sie-vermeiden-sollten" aria-label="Permalink to &quot;Häufige Fehler, die Sie vermeiden sollten&quot;">​</a></h2><p>::: Gefahren Fallstricke <strong>1. Zu viel Inhalt</strong></p><ul><li>Ich versuche, alles abzudecken.</li><li><strong>Korrektur:</strong> Fokus auf Tiefe, nicht auf Breite</li></ul><p><strong>2. Reflexion überspringen</strong></p><ul><li>Eile zur nächsten Aktivität</li><li><strong>Behebung:</strong> Verarbeitungszeit einbauen</li></ul><p><strong>3. Widerstand ignorieren</strong></p><ul><li>Skepsis überwinden</li><li><strong>Lösung:</strong> Sprechen Sie es direkt mit verbalem Aikido an.</li></ul><p><strong>4. Technisches Coaching während der Theorie</strong></p><ul><li>Rollenmischung</li><li><strong>Behebung:</strong> Klare Abgrenzung zwischen MPC und technischem Coach</li></ul><p><strong>5. Keine Nachverfolgung</strong> Das Wochenende ist vorbei, der Unterricht endet.</p><ul><li><strong>Behebung:</strong> Nachbereitungstermine für das Camp planen :::</li></ul><h2 id="ressourcen" tabindex="-1">Ressourcen <a class="header-anchor" href="#ressourcen" aria-label="Permalink to &quot;Ressourcen&quot;">​</a></h2><h3 id="von-dieser-website" tabindex="-1">Von dieser Website <a class="header-anchor" href="#von-dieser-website" aria-label="Permalink to &quot;Von dieser Website&quot;">​</a></h3><ul><li><a href="./workshop">Workshop-Leitfaden</a> - Ausführliche Moderationsprotokolle</li><li><a href="./training-session">Leitfaden für die Trainingssitzung</a> - Für fortlaufendes Üben</li><li><a href="./education/nutrition/">Ernährung</a> - Wettkampftagsprotokolle</li><li><a href="./education/mental-strength/">Mentale Stärke</a> - Konzepte des inneren Spiels</li><li><a href="./education/mindfulness/">Achtsamkeit</a> - Präsenztechniken</li><li><a href="./education/tactics/">Taktiken</a> - Strategisches Denken</li></ul><h3 id="empfohlene-lekture" tabindex="-1">Empfohlene Lektüre <a class="header-anchor" href="#empfohlene-lekture" aria-label="Permalink to &quot;Empfohlene Lektüre&quot;">​</a></h3><ul><li><em>Das innere Spiel des Tennis</em> von Timothy Gallwey</li><li><em>Mindset</em> von Carol Dweck</li><li><em>Die furchtlose Organisation</em> von Amy Edmondson</li></ul>',74)),l(f)])}]]);export{g as __pageData,d as default};
